source:
(()=>{
/* Bài 6 — Hàm cơ bản (mở rộng, chuẩn tường minh, 19/10/2026)
   Bối cảnh: quầy trà sữa của lớp, cùng một việc (chào khách, in nhãn, tính tiền) lặp lại ở nhiều chỗ.
   Tiết 1 = Chặng 1 (hàm void, lời gọi hàm, tham số), tiết 2 = Chặng 2 (hàm int, return, dùng lại hàm trong vòng lặp)
   và Chặng chứng chỉ. Mỗi chặng 6 tab (VAN_PHONG.md). Phần setup()/loop() kiểu Arduino để ở "Tìm hiểu thêm".
*/
"use strict";

const { scratch, boiCanh, bang, ghiVo, luuY, chiTiet, timThem, sauTab, huongDanDoan, bonBuoc, tuCham } = window.KIT;
const strip = code => window.CPP.stripComments(code);
const H0 = "#include <iostream>\nusing namespace std;\n";

/* ---------- Chặng 1: hàm void, lời gọi, tham số ---------- */
const CHAO = H0 + `void chaoKhach() {
    cout << "Xin chao quy khach!" << endl;
}
int main() {
    chaoKhach();
    cout << "Moi chon mon" << endl;
    chaoKhach();
    return 0;
}`;
const KHONG_GOI = H0 + `void chaoKhach() {
    cout << "Xin chao quy khach!" << endl;
}
int main() {
    cout << "Moi chon mon" << endl;
    return 0;
}`;
const NHAN = H0 + `void inNhan(int so) {
    cout << "Ly so " << so << endl;
}
int main() {
    inNhan(3);
    inNhan(7);
    return 0;
}`;
const LOI_GOI = H0 + `void chaoKhach() {
    cout << "Xin chao quy khach!" << endl;
}
int main() {
    ChaoKhach();
    return 0;
}`;
const HOA_DON_KHUNG = H0 + `// Viet ham inHoaDon(int soLy) o day: in "So ly: " va soLy, roi "Tong tien: " va soLy * 25000

int main() {
    int soLy;
    cout << "Nhap so ly: ";
    cin >> soLy;
    // Goi ham inHoaDon voi soLy

    return 0;
}`;

/* ---------- Chặng 2: hàm int, return, dùng lại ---------- */
const TIEN = H0 + `int tinhTien(int soLy) {
    return soLy * 25000;
}
int main() {
    cout << "2 ly: " << tinhTien(2) << endl;
    cout << "Hai don: " << tinhTien(1) + tinhTien(3);
    return 0;
}`;
const TONG = H0 + `int tinhTien(int soLy) {
    return soLy * 25000;
}
int main() {
    int tong = 0;
    for (int i = 1; i <= 3; i++) {
        tong = tong + tinhTien(i);
    }
    cout << "Doanh thu: " << tong;
    return 0;
}`;
const VOID_IN = H0 + `void inTien(int soLy) {
    cout << soLy * 25000 << endl;
}
int main() {
    inTien(2);
    cout << "Xong";
    return 0;
}`;
const PHI_KHUNG = H0 + `// Viet ham int tinhPhiGiao(int tongTien): tu 100000 tra ve 0, con lai tra ve 15000

int main() {
    int tongTien;
    cout << "Nhap tong tien: ";
    cin >> tongTien;
    // In "Phi giao: " va tinhPhiGiao(tongTien), xuong dong
    // In "Phai tra: " va tongTien + tinhPhiGiao(tongTien)

    return 0;
}`;
const NHIEU_DON_KHUNG = H0 + `// Viet ham int tinhTien(int soLy, int gia): tra ve soLy * gia

int main() {
    int n;
    cout << "Nhap so don: ";
    cin >> n;
    int tong = 0;
    // Vong lap: moi don in "Don i: ", nhap soLy, cong tinhTien(soLy, 20000) vao tong

    cout << "Doanh thu: " << tong;
    return 0;
}`;

const BON_BUOC_1 = bonBuoc([["Hiểu đề", "việc nào lặp lại ở nhiều chỗ? Đặt cho việc đó một cái tên."],
  ["Chọn hàm", "hàm làm gì, cần nhận vào giá trị nào (tham số), có trả về kết quả không (void hay int)?"],
  ["Viết màn hình mong đợi trước", "mỗi lời gọi hàm in ra những dòng nào?"],
  ["Viết, chạy, so sánh, sửa", "chạy với từng test case, kiểm tra hàm đã được gọi đúng tên, đủ tham số."]]);

window.LESSON = {
  id: "bai06",
  chuan: 2,
  number: 6,
  title: "Hàm cơ bản (mở rộng)",
  story: "Quầy trà sữa dùng lại công việc",
  badge: { icon: "🧩", name: "Người đóng gói công việc" },
  skills: ["Định nghĩa hàm", "Lời gọi hàm", "Hàm void", "Tham số", "Hàm int và return", "Dùng lại hàm trong vòng lặp"],
  certNote: "Nộp kèm: link Programiz bài làm nhóm và bài cá nhân",

  errorTable: [
    ["Máy báo không biết tên hàm", "Gọi sai chữ hoa, chữ thường (<code>ChaoKhach</code> và <code>chaoKhach</code>)", "Gọi đúng tên giống hệt lúc định nghĩa"],
    ["Máy báo chưa biết hàm dù đã viết", "Hàm được viết <strong>sau</strong> <code>main()</code>", "Viết hàm ở <strong>trên</strong> <code>main()</code>"],
    ["Chạy được nhưng hàm không in gì", "Chỉ định nghĩa hàm mà không gọi trong <code>main()</code>", "Thêm lời gọi: <code>chaoKhach();</code>"],
    ["Lỗi khi gọi hàm có tham số", "Truyền thiếu hoặc thừa giá trị", "Truyền đủ, đúng thứ tự: <code>inNhan(3);</code>"],
    ["Hàm int không đưa kết quả về", "Thiếu câu lệnh <code>return</code>", "Thêm <code>return ketQua;</code> ở cuối hàm"]
  ],

  steps: [
    /* ================= CHẶNG 1 · TIẾT 1 · hàm void, tham số ================= */
    {
      kind: "stage", id: "stage-1", number: 1, nav: "Chặng 1",
      kicker: "CHẶNG 1 · TIẾT 1 · HÀM void, LỜI GỌI HÀM VÀ THAM SỐ",
      title: "Đặt tên cho một công việc",
      bit: "Chào bạn! Chặng này có 6 phần. Làm xong mỗi phần, bấm <strong>Tiếp</strong> ở cuối trang.",
      objectives: ["Định nghĩa hàm void và gọi hàm trong main()",
        "Giải thích thứ tự máy chạy khi gặp lời gọi hàm",
        "Truyền giá trị cho hàm qua tham số"],
      flow: [
        { label: "Bối cảnh", title: "Câu chào khách lặp lại ở nhiều chỗ",
          html: boiCanh("Máy tính tiền của quầy chào khách lúc khách đến và lúc khách về. Nếu viết lại câu lệnh chào ở mọi chỗ, chương trình dài và khó sửa: muốn đổi câu chào phải sửa nhiều nơi.",
            `<p>Lập trình viên gom một công việc thành một <strong>hàm</strong> và đặt tên cho nó, ví dụ <code>chaoKhach</code>. Viết hàm một lần (<strong>định nghĩa hàm</strong>), rồi cần làm việc đó ở đâu thì chỉ cần viết tên hàm (<strong>lời gọi hàm</strong>). Bạn đã dùng một hàm đặc biệt từ Bài 1: hàm <code>main()</code>, nơi chương trình bắt đầu chạy.</p>
             <p>Ở chặng này, bạn sẽ chạy từng dòng để thấy máy nhảy vào hàm rồi quay lại <code>main()</code>, và truyền số ly cho hàm qua <strong>tham số</strong>.</p>`) + sauTab("Kiểm chứng") },
        { label: "Đoán rồi chạy", title: "Gọi hàm, quên gọi hàm và tham số", tasks: ["c1-dc1", "c1-dc2", "c1-dc3"],
          html: huongDanDoan(3) + `<p>Để ý mũi tên: khi gặp lời gọi hàm, máy nhảy lên chạy các câu lệnh trong hàm, chạy xong thì quay lại dòng ngay sau lời gọi.</p>` },
        { label: "Kiểm chứng", title: "Định nghĩa hay lời gọi?", tasks: ["c1-goi", "c1-ghep", "c1-dungsai"],
          code: CHAO, focus: [3, 7, 9],
          html: `<p>Khung bên trái là chương trình ở <strong>Lần 1</strong>. Dựa vào thứ tự máy chạy bạn vừa thấy, trả lời các câu hỏi bên cạnh.</p>` },
        { label: "Ghi nhớ", title: "Hàm void, lời gọi hàm và tham số",
          html: ghiVo(["<code>void tenHam() { … }</code>: định nghĩa hàm không trả về giá trị; viết ở trên <code>main()</code>.",
                "<code>tenHam();</code>: lời gọi hàm. Máy chạy các câu lệnh trong hàm, xong thì quay lại ngay sau lời gọi.",
                "<code>void inNhan(int so)</code>: <code>so</code> là tham số, nhận giá trị từ lời gọi <code>inNhan(3);</code>."])
            + luuY("chỉ định nghĩa mà không gọi thì hàm không chạy. Gọi hàm phải đúng tên (phân biệt chữ hoa, chữ thường) và có cặp ngoặc <code>( )</code>.")
            + chiTiet
            + bang("1. Khái niệm", ["Thuật ngữ", "Định nghĩa", "Ví dụ"], [
              ["Hàm", "Một nhóm câu lệnh được đặt tên, làm một công việc, có thể gọi lại nhiều lần.", "<code>chaoKhach</code>"],
              ["Định nghĩa hàm", "Phần viết ra hàm: kiểu trả về, tên, tham số và thân hàm trong <code>{ }</code>.", "<code>void chaoKhach() { … }</code>"],
              ["Lời gọi hàm", "Câu lệnh yêu cầu máy chạy hàm: tên hàm và cặp ngoặc.", "<code>chaoKhach();</code>"],
              ["<code>void</code>", "Kiểu của hàm chỉ làm việc (ví dụ in ra), không trả về giá trị.", "<code>void inNhan(int so)</code>"],
              ["Tham số", "Biến của hàm, nhận giá trị được truyền vào ở lời gọi.", "<code>so</code> nhận 3 khi gọi <code>inNhan(3)</code>"]])
            + bang("2. Thứ tự máy chạy ở Lần 1", ["Bước", "Dòng", "Máy làm gì"], [
              ["1", "7", "gọi <code>chaoKhach()</code> → nhảy lên dòng 3"],
              ["2", "4", "in Xin chao quy khach!, hết hàm → quay về dòng 8"],
              ["3", "8", "in Moi chon mon"],
              ["4", "9", "gọi lại <code>chaoKhach()</code> → chạy dòng 4 lần nữa"]])
            + timThem([["https://www.w3schools.com/cpp/cpp_functions.asp", "W3Schools · Hàm"],
                       ["https://www.w3schools.com/cpp/cpp_function_param.asp", "W3Schools · Tham số"],
                       ["https://www.programiz.com/cpp-programming/function", "Programiz · Hàm C++"]]) },
        { label: "Luyện tập", title: "Điền, rồi tự viết hàm in hoá đơn", tasks: ["c1-dien", "c1-viet"], html: BON_BUOC_1 },
        { label: "Phản tư", title: "Bạn đã chắc đến đâu?", tasks: ["c1-tucham"], stop: true,
          html: `<p>${tuCham}</p>`, bit: "Xong Chặng 1! Dừng lại và nhìn lên bảng." }
      ],
      challenges: [
        { id: "c1-dc1", type: "doanchay", predict: true, icon: "🔮",
          title: "Lần 1 · Gọi hàm hai lần",
          prompt: "Dòng 3–5 định nghĩa hàm <code>chaoKhach</code>. Trong <code>main()</code>, hàm được gọi ở dòng 7 và dòng 9.",
          ask: "Theo bạn, màn hình sẽ hiện gì?",
          code: CHAO, focus: [7, 9],
          options: ["Xin chao quy khach!\nMoi chon mon\nXin chao quy khach!", "Moi chon mon", "Xin chao quy khach!\nMoi chon mon", "Moi chon mon\nXin chao quy khach!\nXin chao quy khach!"],
          answer: "Xin chao quy khach!\nMoi chon mon\nXin chao quy khach!",
          trace: [
            { l: 6, why: "Máy bỏ qua phần định nghĩa hàm và bắt đầu chạy từ <code>main()</code>." },
            { l: 7, why: "Lời gọi <code>chaoKhach();</code>: máy nhảy lên thân hàm ở dòng 4." },
            { l: 4, out: "Xin chao quy khach!\n", why: "Chạy câu lệnh trong hàm: in lời chào. Hết hàm, máy quay lại ngay sau dòng 7." },
            { l: 8, out: "Moi chon mon\n", why: "Quay lại <code>main()</code>, in Moi chon mon." },
            { l: 9, why: "Gọi <code>chaoKhach();</code> lần thứ hai: lại nhảy lên dòng 4." },
            { l: 4, out: "Xin chao quy khach!\n", why: "Hàm chạy lại từ đầu, in lời chào lần nữa." },
            { l: 10, why: "<code>return 0;</code> kết thúc chương trình." }],
          whyRight: "Mỗi lời gọi chạy hàm một lần; giữa hai lần gọi là dòng Moi chon mon.",
          why: "Máy chạy theo thứ tự trong main(): gọi hàm (in lời chào), in Moi chon mon, rồi gọi hàm lần nữa. Mỗi lời gọi chạy thân hàm một lần." },
        { id: "c1-dc2", type: "doanchay", predict: true, icon: "🔮", after: "c1-dc1",
          title: "Lần 2 · Quên gọi hàm",
          prompt: "Chương trình này vẫn định nghĩa hàm <code>chaoKhach</code> ở dòng 3–5, nhưng trong <code>main()</code> không có lời gọi hàm nào.",
          ask: "Theo bạn, màn hình sẽ hiện gì?",
          code: KHONG_GOI, focus: [7],
          options: ["Moi chon mon", "Xin chao quy khach!\nMoi chon mon", "Xin chao quy khach!", "Moi chon mon\nXin chao quy khach!"],
          answer: "Moi chon mon",
          trace: [
            { l: 6, why: "Máy bắt đầu từ <code>main()</code>. Phần định nghĩa hàm ở trên chỉ mô tả công việc, chưa chạy." },
            { l: 7, out: "Moi chon mon\n", why: "In Moi chon mon." },
            { l: 8, why: "<code>return 0;</code> kết thúc. Hàm chaoKhach không được gọi nên không chạy lần nào." }],
          whyRight: "Định nghĩa hàm không làm hàm chạy; phải có lời gọi hàm trong main().",
          why: "Định nghĩa hàm chỉ mô tả công việc. Không có lời gọi chaoKhach(); trong main() nên máy không chạy hàm, chỉ in Moi chon mon." },
        { id: "c1-dc3", type: "doanchay", predict: true, icon: "🔮", after: "c1-dc2",
          title: "Lần 3 · Truyền số cho hàm",
          prompt: "Hàm <code>inNhan</code> có tham số <code>so</code>. Dòng 7 gọi <code>inNhan(3)</code>, dòng 8 gọi <code>inNhan(7)</code>.",
          ask: "Theo bạn, màn hình sẽ hiện gì?",
          code: NHAN, focus: [3, 7, 8],
          options: ["Ly so 3\nLy so 7", "Ly so so\nLy so so", "Ly so 7\nLy so 3", "Ly so 3\nLy so 3"],
          answer: "Ly so 3\nLy so 7",
          trace: [
            { l: 6, why: "Máy bắt đầu từ <code>main()</code>." },
            { l: 7, mem: ["so", "int", "3"], why: "Gọi <code>inNhan(3)</code>: tham số <code>so</code> nhận giá trị 3, máy nhảy vào hàm." },
            { l: 4, out: "Ly so 3\n", why: "In chuỗi và giá trị của <code>so</code> là 3." },
            { l: 8, mem: ["so", "int", "7"], why: "Gọi <code>inNhan(7)</code>: lần này <code>so</code> nhận giá trị 7." },
            { l: 4, out: "Ly so 7\n", why: "Cùng một hàm, nhưng in giá trị mới của <code>so</code> là 7." },
            { l: 9, why: "<code>return 0;</code> kết thúc chương trình." }],
          whyRight: "Mỗi lời gọi truyền một giá trị khác cho tham số so: 3 rồi 7.",
          why: "Tham số so nhận giá trị ở từng lời gọi: lần đầu 3, lần sau 7. Cùng một hàm in ra hai nhãn khác nhau." },
        { id: "c1-goi", type: "choice", icon: "🔍", title: "Dòng nào là lời gọi hàm?",
          prompt: "Trong chương trình Lần 1 bên trái, dòng nào là <strong>lời gọi hàm</strong>?",
          options: [
            { text: "Dòng 7 và dòng 9" },
            { text: "Dòng 3 và dòng 4", why: "Dòng 3–5 là định nghĩa hàm (viết ra công việc), chưa phải lời gọi." },
            { text: "Dòng 6 và dòng 8", why: "Dòng 6 mở hàm main(); dòng 8 là câu lệnh cout thường." },
            { text: "Chỉ dòng 7 mà thôi", why: "Dòng 9 cũng gọi chaoKhach(); lần thứ hai." }
          ],
          answer: "Dòng 7 và dòng 9", why: "Đúng. chaoKhach(); ở dòng 7 và dòng 9 là hai lời gọi hàm." },
        { id: "c1-ghep", type: "match", icon: "🔗", title: "Ghép thuật ngữ với ví dụ",
          prompt: "Ghép mỗi thuật ngữ về hàm với ví dụ đúng của thuật ngữ đó.",
          pairs: [["Định nghĩa hàm", "<code>void chaoKhach() { … }</code>"], ["Lời gọi hàm", "<code>chaoKhach();</code>"],
            ["Tham số", "<code>so</code> trong <code>void inNhan(int so)</code>"], ["Giá trị truyền vào", "<code>3</code> trong <code>inNhan(3);</code>"]] },
        { id: "c1-dungsai", type: "truefalse", icon: "✅", title: "Đúng hay sai?",
          prompt: "Chọn Đúng hoặc Sai cho từng nhận xét về hàm.",
          items: [
            { text: "Viết xong định nghĩa hàm là hàm tự chạy, không cần gọi.", answer: false, why: "Ở Lần 2, hàm không được gọi nên không chạy." },
            { text: "Một hàm có thể được gọi nhiều lần.", answer: true },
            { text: "Gọi <code>ChaoKhach();</code> cũng chạy được hàm <code>chaoKhach</code>.", answer: false, why: "C++ phân biệt chữ hoa, chữ thường: tên phải giống hệt." },
            { text: "Hàm <code>void</code> không trả về giá trị.", answer: true }
          ] },
        { id: "c1-dien", type: "fill", icon: "✏️", title: "Điền vào chỗ trống",
          prompt: "Quầy cần in nhãn <code>Ly so 5</code> bằng hàm <code>inNhan</code>. Điền vào 2 chỗ trống.",
          template: `#include <iostream>
using namespace std;
[[0]] inNhan(int so) {\n    cout << "Ly so " << so;\n}\nint main() {\n    inNhan([[1]]);\n    return 0;\n}`,
          blanks: [
            { answers: ["void"], options: ["void", "int", "cout", "return"], why: "Hàm chỉ in ra, không trả về giá trị: dùng void." },
            { answers: ["5"], options: ["5", "so", "\"5\"", "Ly so 5"], why: "Truyền giá trị 5 vào tham số so." }
          ],
          screen: "Ly so 5" },
        { id: "c1-viet", type: "code", icon: "🛠️", title: "Tự viết: hàm in hoá đơn",
          prompt: "Viết hàm <code>inHoaDon(int soLy)</code> rồi gọi hàm trong <code>main()</code>. Làm theo chú thích trong khung.",
          card: {
            boiCanh: "Quầy in hoá đơn ở nhiều chỗ trong chương trình. Gom việc in hoá đơn thành hàm inHoaDon, nhận số ly qua tham số. Mỗi ly 25000 đồng.",
            bien: [["int soLy;", "int", "số ly khách gõ (đã nhập trong main)"], ["int soLy (tham số)", "int", "tham số của hàm inHoaDon"]],
